  const handoffPointer = block.match(/handoffs:\n\s+- handoff_id: (.+)\n\s+handoff_version: (\d+)\n\s+handoff_path: (.+)\n\s+handoff_content_sha256: ([0-9a-f]{64})(?:\n|$)/);
  assert.ok(handoffPointer, '작업큐의 최신 HANDOFF pointer가 없습니다.');
  const [, handoffId, rawHandoffVersion, handoffPath, handoffContentSha] = handoffPointer;
